import { expect, test } from 'bun:test'

import { Result } from 'effect'

import { sha256 } from '../../hash'
import { evidence, fixture, preset } from './fixtures.test-support'
import { Profile } from './policy'
import { replayMacroEtfCoreSignals } from './signals'

// Generated by the unmodified Wave 5C signalModel at 4899b0547 on fixture(268).
// The five reviews include both XLC inception and XLRE's observation reset.
test.each([
  [Profile.F2, '18a14eec78b64707443f8e6414404326c661479af2607f4861af12c80679f33b'],
  [Profile.F4, '8a6547247e28df4c80892e03dae1588f850dd29765efbb91173a6b62304a490e'],
] as const)('matches frozen Wave 5C %s dates and all 29 weights', (profile, digest) => {
  const sequence = Result.getOrThrow(replayMacroEtfCoreSignals(preset(profile), evidence(fixture(268))))
  expect(sequence).toHaveLength(5)
  expect(
    sha256(
      JSON.stringify(
        sequence.map(({ signalDate, executionDate, weights }) => [
          signalDate,
          executionDate,
          weights.map((weight) => weight.toFixed(12)),
        ]),
      ),
    ),
  ).toBe(digest)
})
